/* ==================== Courses + Recruiting profile ==================== */
function courseState() { if (!S.courses || typeof S.courses !== 'object') S.courses = {}; if (!S.courses.done) S.courses.done = {}; return S.courses; }
function courseProgress(c) { var d = courseState().done, n = c.lessons.filter(function (l, i) { return d[c.id + ':' + i]; }).length; return { n: n, total: c.lessons.length, pct: Math.round((n / c.lessons.length) * 100), next: c.lessons.findIndex(function (l, i) { return !d[c.id + ':' + i]; }) }; }
function courseCard(c) {
  var p = courseProgress(c), mins = sum(c.lessons, function (l) { return l.m; });
  return '<a class="course" href="#course-' + c.id + '" style="--cc:' + c.color + '"><div class="co-top"><span class="co-area">' + esc(c.area) + '</span>' + ringChart(p.pct, c.title) + '</div><h3>' + esc(c.title) + '</h3><p class="small ink2">' + esc(c.blurb) + '</p><div class="tiny">' + c.lessons.length + ' lessons · ' + mins + ' min</div><div class="co-cta">' + (p.n === p.total ? ic('trophy', 15) + ' Completed' : p.n ? 'Continue: ' + esc(c.lessons[p.next].t) : 'Start course') + ' ' + ic('arrow-right', 14) + '</div></a>';
}
function viewCourses() {
  var started = COURSES.filter(function (c) { var p = courseProgress(c); return p.n && p.n < p.total; });
  return pageHead('Courses', 'Learn the game, then train it', '') + (started.length ? '<div class="kick" style="margin-bottom:8px">In progress</div><div class="courses" style="margin-bottom:22px">' + started.map(courseCard).join('') + '</div><div class="kick" style="margin-bottom:8px">All courses</div>' : '') + '<div class="courses">' + COURSES.map(courseCard).join('') + '</div><p class="tiny" style="margin-top:14px">Each lesson has the key coaching points and drills that practice them. "Practice these drills" starts them in the workout runner and logs a real session.</p>';
}
function viewCourse(id) {
  var parts = id.split('-'), c = COURSES.find(function (x) { return x.id === parts[0]; }); if (!c) return viewCourses();
  var p = courseProgress(c), open = parts[1] != null ? +parts[1] : (p.next >= 0 ? p.next : 0), d = courseState().done;
  return '<a class="crumb" href="#courses">' + ic('chevron-left', 14) + ' Courses</a><section class="panel course-hero" style="--cc:' + c.color + '"><div class="row"><div><div class="kick">' + esc(c.area) + ' course</div><h1>' + esc(c.title) + '</h1><p class="ink2">' + esc(c.blurb) + '</p></div>' + ringChart(p.pct, 'Course progress') + '</div><div class="bar" style="margin-top:10px"><i style="width:' + p.pct + '%"></i></div><div class="tiny" style="margin-top:6px">' + p.n + ' of ' + p.total + ' lessons complete</div></section>' +
    '<div class="lessons">' + c.lessons.map(function (l, i) { var isOpen = i === open, done = !!d[c.id + ':' + i];
      return '<section class="lesson' + (isOpen ? ' open' : '') + (done ? ' done' : '') + '"><a class="lh" href="#course-' + c.id + '-' + i + '"><span class="ln">' + (done ? ic('check', 16) : i + 1) + '</span><span class="grow"><b>' + esc(l.t) + '</b><span class="tiny">' + l.m + ' min' + (l.drills.length ? ' · ' + l.drills.length + ' drill' + (l.drills.length === 1 ? '' : 's') : '') + '</span></span>' + ic(isOpen ? 'chevron-left' : 'chevron-right', 16) + '</a>' +
        (isOpen ? '<div class="lb"><ul class="pts">' + l.pts.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>' + (l.drills.length ? '<h4>Practice it</h4><div class="list">' + l.drills.map(function (did) { var dr = drillById(did); return dr ? '<a class="tapwrap" href="#drill-' + did.slice(2) + '"><div class="main"><b class="nm">' + esc(dr.name) + '</b><div class="tiny">' + esc(dr.objective) + '</div></div><span class="tag">' + dr.minutes + ' min</span></a>' : ''; }).join('') + '</div>' : '') +
          '<div class="btns" style="margin-top:14px">' + (l.drills.length ? '<button class="btn p" data-a="course-practice" data-id="' + c.id + '" data-i="' + i + '">' + ic('play', 16) + ' Practice these drills</button>' : '') + '<button class="btn' + (done ? '' : ' b') + '" data-a="course-done" data-id="' + c.id + '" data-i="' + i + '">' + (done ? 'Mark not done' : ic('check', 16) + ' Mark lesson complete') + '</button></div></div>' : '') + '</section>'; }).join('') + '</div>';
}
ACT['course-done'] = function (el) { var k = el.dataset.id + ':' + el.dataset.i, d = courseState().done; if (d[k]) delete d[k]; else d[k] = today(); save(); var c = COURSES.find(function (x) { return x.id === el.dataset.id; }), p = courseProgress(c); if (d[k]) toast(p.n === p.total ? 'Course complete: ' + c.title : 'Lesson complete'); location.hash = '#course-' + el.dataset.id + (d[k] && p.next >= 0 ? '-' + p.next : '-' + el.dataset.i); render(); };
ACT['course-practice'] = function (el) { var c = COURSES.find(function (x) { return x.id === el.dataset.id; }), l = c.lessons[+el.dataset.i]; var items = l.drills.map(drillById).filter(Boolean).map(function (d) { return { drillId: d.id, name: d.name, category: d.category, metric: d.metric, targetSets: d.sets, targetAttempts: d.attempts, restSec: 30, timeLimitSec: 0 }; }); startRun(items, c.title + ': ' + l.t, null, null); };

/* ---------- recruiting profile ---------- */
function recruitState() { if (!S.recruit || typeof S.recruit !== 'object') S.recruit = { stats: {}, links: [] }; if (!S.recruit.stats) S.recruit.stats = {}; if (!Array.isArray(S.recruit.links)) S.recruit.links = []; return S.recruit; }
function trainingProof() {
  var t = today(), from = addDays(t, -89), ss = rangeSessions(from, t), sets = shotSets(from, t), st = splitStats(sets);
  return { sessions: ss.length, mins: sum(ss, function (s) { return s.minutes || 0; }), shots: st.tot.att, fg: pct(st.tot.made, st.tot.att), three: st.three.att >= 25 ? pct(st.three.made, st.three.att) : null, threeAtt: st.three.att, ft: st.ft.att >= 20 ? pct(st.ft.made, st.ft.att) : null, ftAtt: st.ft.att };
}
function playerCardHTML() {
  var r = recruitState(), c = coachState(), p = S.profile, tp = trainingProof(), s = r.stats;
  var stat = function (v, l) { return v ? '<div><b>' + esc(v) + '</b><span>' + l + '</span></div>' : ''; };
  var statsRow = [stat(s.ppg, 'PPG'), stat(s.rpg, 'RPG'), stat(s.apg, 'APG'), stat(s.spg, 'SPG'), stat(s.fg && s.fg + '%', 'FG%'), stat(s.tp && s.tp + '%', '3P%'), stat(s.ft && s.ft + '%', 'FT%')].join('');
  var meas = [stat(r.height, 'Height'), stat(r.weight && r.weight + ' lb', 'Weight'), stat(r.wingspan, 'Wingspan'), stat(r.vertical && r.vertical + '"', 'Vertical'), stat(r.sprint && r.sprint + 's', '¾-court sprint'), stat(r.agility && r.agility + 's', 'Lane agility')].join('');
  return '<article class="pcard" id="pcard"><header><div class="pc-num">' + esc(r.number || '') + '</div><div><div class="pc-kick">' + esc(c.position || 'Guard') + (c.gradYear ? ' · Class of ' + esc(c.gradYear) : '') + '</div><h2>' + esc(p.name || 'Your name') + '</h2><div class="pc-sub">' + esc([r.school, r.team].filter(Boolean).join(' · ') || 'School · Club team') + (r.gpa ? ' · GPA ' + esc(r.gpa) : '') + '</div></div></header>' +
    (statsRow ? '<section><h4>' + esc(r.season || 'Season') + ' stats</h4><div class="pc-grid">' + statsRow + '</div></section>' : '') + (meas ? '<section><h4>Measurables</h4><div class="pc-grid">' + meas + '</div></section>' : '') +
    (tp.sessions ? '<section><h4>Training, last 90 days <span>tracked in Training Center</span></h4><div class="pc-grid"><div><b>' + tp.sessions + '</b><span>Sessions</span></div><div><b>' + Math.round(tp.mins / 60) + '</b><span>Hours</span></div>' + (tp.shots ? '<div><b>' + tp.shots + '</b><span>Shots tracked</span></div>' : '') + (tp.three != null ? '<div><b>' + tp.three + '%</b><span>3PT in workouts (' + tp.threeAtt + ')</span></div>' : '') + (tp.ft != null ? '<div><b>' + tp.ft + '%</b><span>FT in workouts (' + tp.ftAtt + ')</span></div>' : '') + '</div></section>' : '') +
    (r.bio ? '<section><h4>About</h4><p>' + esc(r.bio) + '</p></section>' : '') +
    (r.links.length ? '<section><h4>Film</h4>' + r.links.map(function (l) { return '<a class="pc-link" href="' + esc(l) + '" target="_blank" rel="noopener">' + esc(l.replace(/^https?:\/\//, '').slice(0, 60)) + '</a>'; }).join('') + '</section>' : '') +
    '<footer>' + [r.email, r.phone].filter(Boolean).map(esc).join(' · ') + (r.coachName ? '<br>Coach: ' + esc(r.coachName) + (r.coachContact ? ' · ' + esc(r.coachContact) : '') : '') + '</footer></article>';
}
function viewRecruit() {
  var r = recruitState(), s = r.stats;
  var fld = function (n, l, v, ph, cls) { return '<div class="fld' + (cls ? ' ' + cls : '') + '"><label class="f" for="rc-' + n + '">' + l + '</label><input id="rc-' + n + '" name="' + n + '" value="' + esc(v || '') + '" placeholder="' + esc(ph || '') + '"></div>'; };
  return pageHead('Recruiting', 'Your player profile', '<div class="btns"><button class="btn sm" data-a="rc-print">' + ic('printer', 15) + ' Print / PDF</button><button class="btn sm" data-a="rc-dl">' + ic('download', 15) + ' Download</button></div>') +
    '<div class="grid recruit"><form data-form="recruit" class="stack"><section class="panel"><h3>Basics</h3><div class="grid g2" style="margin-top:10px">' + fld('school', 'High school', r.school, 'Your school') + fld('team', 'Club / AAU team', r.team) + fld('number', 'Jersey #', r.number) + fld('gpa', 'GPA', r.gpa, 'e.g. 3.6') + fld('email', 'Email', r.email) + fld('phone', 'Phone', r.phone) + '</div><p class="tiny">Name, position and class year come from your Coach assessment.</p></section>' +
    '<section class="panel"><h3>Measurables</h3><div class="grid g3" style="margin-top:10px">' + fld('height', 'Height', r.height, '6\'1"') + fld('weight', 'Weight (lb)', r.weight) + fld('wingspan', 'Wingspan', r.wingspan, '6\'4"') + fld('vertical', 'Vertical (in)', r.vertical) + fld('sprint', '¾-court sprint (s)', r.sprint) + fld('agility', 'Lane agility (s)', r.agility) + '</div></section>' +
    '<section class="panel"><h3>Season stats</h3><div class="grid g4" style="margin-top:10px">' + fld('season', 'Season', r.season, '2026–27 Varsity', 'span2') + fld('s:ppg', 'PPG', s.ppg) + fld('s:rpg', 'RPG', s.rpg) + fld('s:apg', 'APG', s.apg) + fld('s:spg', 'SPG', s.spg) + fld('s:fg', 'FG%', s.fg) + fld('s:tp', '3P%', s.tp) + fld('s:ft', 'FT%', s.ft) + '</div><p class="tiny">Enter real game stats only. Training numbers are added separately and labelled as workouts.</p></section>' +
    '<section class="panel"><h3>Story & film</h3><div class="fld" style="margin-top:10px"><label class="f" for="rc-bio">About you (2–4 sentences)</label><textarea id="rc-bio" name="bio" placeholder="What kind of player are you? What do you bring to a team?">' + esc(r.bio || '') + '</textarea></div><div class="fld"><label class="f" for="rc-links">Highlight links (one per line)</label><textarea id="rc-links" name="links" placeholder="https://…">' + esc(r.links.join('\n')) + '</textarea></div><div class="grid g2">' + fld('coachName', 'Coach reference', r.coachName) + fld('coachContact', 'Coach contact', r.coachContact) + '</div></section>' +
    '<button class="btn p xl" type="submit">' + ic('check', 18) + ' Save profile</button></form><div class="pc-wrap"><div class="kick" style="margin-bottom:8px">Preview</div>' + playerCardHTML() + '</div></div>';
}
FORM['recruit'] = function (f) {
  var r = recruitState(); ['school', 'team', 'number', 'gpa', 'email', 'phone', 'height', 'weight', 'wingspan', 'vertical', 'sprint', 'agility', 'season', 'bio', 'coachName', 'coachContact'].forEach(function (k) { if (f[k]) r[k] = f[k].value.trim(); });
  ['ppg', 'rpg', 'apg', 'spg', 'fg', 'tp', 'ft'].forEach(function (k) { var el = f.querySelector('[name="s:' + k + '"]'); if (el) r.stats[k] = el.value.trim(); });
  var bad = f.links.value.split(/\n+/).map(function (x) { return x.trim(); }).filter(Boolean).filter(function (x) { return !/^https?:\/\//i.test(x); });
  if (bad.length) { toast('Links must start with https://', 'warn'); return; }
  r.links = f.links.value.split(/\n+/).map(function (x) { return x.trim(); }).filter(Boolean).slice(0, 8);
  save(); toast('Profile saved'); render();
};
ACT['rc-print'] = function () { document.body.classList.add('print-card'); var done = function () { document.body.classList.remove('print-card'); window.removeEventListener('afterprint', done); }; window.addEventListener('afterprint', done); window.print(); setTimeout(done, 1500); };
ACT['rc-dl'] = function () {
  var css = ''; try { css = Array.prototype.map.call(document.styleSheets, function (sh) { try { return Array.prototype.map.call(sh.cssRules, function (r) { return r.cssText; }).join('\n'); } catch (e) { return ''; } }).join('\n'); } catch (e) { css = ''; }
  var html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(S.profile.name || 'Player') + ' · Player profile</title><style>' + css + 'body{padding:24px;display:flex;justify-content:center}</style></head><body>' + playerCardHTML() + '</body></html>';
  var a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([html], { type: 'text/html' })); a.download = (S.profile.name || 'player').replace(/\s+/g, '-').toLowerCase() + '-profile.html'; document.body.appendChild(a); a.click(); setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500); toast('Profile downloaded');
};
